R=[
(55203,"Kue Angel Food Sherbet","Kue Angel Food Sherbet yang mudah ini hanya menggunakan tiga bahan dan merupakan makanan penutup lezat yang dapat masuk dalam diet ramah ginjal.","10","1/10 kue",
["Satu wadah 16 ons topping krim kocok nonsusu bebas gula","1-1/2 kuart wadah Rainbow Sherbet","Kue Angel Food beli jadi (atau buatan sendiri)"],
["Cairkan topping krim kocok dan sherbet.","Potong kue secara horizontal di bagian tengah untuk membuat bagian atas dan bawah kue.","Oleskan sherbet dengan tebal di atas bagian bawah kue, setebal ~ 4-5 inci. Letakkan bagian atas kue di atas sherbet.","Lapisi seluruh kue dengan topping krim kocok. Masukkan ke dalam freezer selama 4-6 jam. Keluarkan dari freezer saat siap disajikan."],
["Carilah kue angel food beli jadi tanpa atau dengan zat tambahan fosfor minimal dalam daftar bahannya.","Boleh menggunakan topping krim kocok biasa, tetapi akan meningkatkan gula tambahan sekitar ~20 gram atau lebih.","Makanan penutup ini adalah sajian sesekali, tidak cocok untuk penderita diabetes","Boleh mencoba berbagai rasa sherbet jika diinginkan."],
["1 pengganti susu","1-1/2 pati","2 tinggi kalori","1 lemak"]),
(1002590,"Omelet Beach Boy","Ingin merasa seperti di pantai sambil menikmati sarapan ramah ginjal? Tak perlu mencari jauh—Omelet Beach Boy hadir untuk kebutuhan diet ginjal Anda.","1","1 omelet",
["2 sendok makan bawang bombai","2 sendok makan paprika hijau","1 sendok makan minyak canola","2 sendok makan kentang segar","1 butir telur utuh","2 putih telur","2 sendok makan pemutih kopi nonsusu","2 tangkai peterseli segar untuk hiasan"],
["Cincang bawang bombai dan paprika hijau. Parut kentang.","Panaskan minyak dalam wajan antilengket. Masukkan bawang bombai dan paprika hijau; tumis selama 2 menit. Tambahkan kentang parut dan masak selama 5 menit hingga kecokelatan, dibalik sekali. Angkat dari wajan dan sisihkan.","Semprot wajan dengan minyak dan panaskan dengan api sedang. Kocok telur dengan pemutih kopi nonsusu dan tuangkan ke dalam wajan. Masak hingga telur matang.","Letakkan kentang parut di tengah omelet. Lipat kedua sisi omelet dengan spatula, lalu geser ke piring.","Hiasi dengan tangkai peterseli dan bumbui sesuai selera."],
["Untuk omelet dengan kalium lebih rendah, rendam kentang parut segar atau beku dalam 2 cangkir air selama 2 jam. Letakkan di atas serbet dapur yang bersih, tutup dan gulung untuk membuang kelebihan air sebelum dimasak. Ini mengurangi kandungan kalium sekitar 43 miligram."],
["2 daging","1/2 pati","1/2 sayuran, rendah kalium","1 lemak"]),
(1002592,"Salad Kebun","Salad yang mudah ini dapat menambahkan sentuhan warna pada hidangan Anda.","4","1/4 resep",
["200 gram selada","1 wortel besar","1 batang seledri","1/2 paprika merah kecil","4 sendok makan minyak sayur","5 sendok makan jagung manis","2 sendok makan air lemon","lada secukupnya"],
["Bilas daun selada dengan air panas selama 5 detik, lalu segera bilas dengan air dingin. Tiriskan dan potong menjadi potongan kecil.","Parut wortel. Potong seledri dan paprika menjadi irisan korek api.","Tumis biji jagung dalam 1 sendok makan minyak dengan api sedang selama beberapa menit hingga empuk dan keemasan. Angkat dan biarkan dingin.","Dalam cangkir, campurkan sisa 3 sendok makan minyak, air lemon, dan lada.","Campurkan semuanya dalam 1 mangkuk besar, tambahkan vinaigrette dan aduk. Sajikan segera."],
["Pilihlah minyak zaitun untuk salad dan sayuran; Anda boleh tidak menambahkan vinaigrette pada salad. Cuka dapat digunakan sebagai pengganti minyak zaitun."],
["1 sayuran, kalium sedang"]),
(1002597,"Sup Daging Sapi dan Sayuran","Semur dan sup adalah makanan penghibur tradisional. Sup Daging Sapi dan Sayuran adalah sup ramah ginjal dengan semua cita rasa lezat dari sup yang dulu dibuat Ibu.","3","1 mangkuk sup sedang atau 250 mL",
["1 wortel sedang","1 paprika kecil","1 bawang bombai putih sedang","100 gram buncis","1 batang seledri kecil","1 tangkai daun ketumbar","150 gram kentang","200 gram daging sapi tanpa lemak","3 siung bawang putih"],
["Kupas wortel dan paprika.","Cuci semua sayuran dan cincang menjadi potongan kecil.","Kupas kentang dan potong-potong. Letakkan dalam panci dan tutup seluruhnya dengan air. Didihkan dan tiriskan. Ulangi prosesnya dan sisihkan.","Bersihkan daging sapi tanpa lemak dan potong menjadi potongan kecil.","Haluskan siung bawang putih.","Letakkan panci berisi air yang cukup untuk memasak bahan-bahan di atas api besar dan masukkan bahan-bahan.","Aduk terus selama 30 menit hingga bahan-bahan matang.","Sajikan panas."],
["Merebus kentang dua kali mengurangi kandungan kaliumnya."],
["2 daging","1/2 pati","2 sayuran, kalium sedang"]),
(1002604,"Udang Bertepung Roti","Udang Bertepung Roti adalah resep yang menambah cita rasa pada udang berukuran apa pun. Sebagai pengganti adonan tepung terigu, resep ini menggunakan adonan tepung maizena yang dilanjutkan dengan lapisan remah roti.","4","4 udang besar",
["1 pon udang besar","1 sendok teh lada","1 sendok teh bawang putih bubuk","2 sendok makan air lemon","1 cangkir minyak","1-1/2 cangkir tepung maizena","1 cangkir air","2 butir telur","1-1/2 cangkir remah roti"],
["Bersihkan udang, buang kulitnya, buang urat punggungnya dan belah sepanjang punggung agar terbuka seperti kupu-kupu.","Tambahkan lada, bawang putih, dan air lemon.","Panaskan minyak dalam wajan.","Dalam mangkuk, campurkan tepung maizena, air, dan telur.","Celupkan udang satu per satu hingga terlapisi sempurna dengan adonan.","Gulingkan dalam remah roti.","Goreng udang hingga cokelat keemasan."],
["Untuk bumbu tambahan, cobalah menambahkan lada cayenne."],
["3 daging","2 pati"]),
(1002610,"Minuman Penyegar Semangka Musim Panas","Segarkan diri dengan resep ramah ginjal ini – Minuman Penyegar Semangka Musim Panas.","2","3/4 cangkir (6 ons)",
["1 cangkir es serut","1 cangkir semangka tanpa biji, dipotong dadu","2 sendok teh air jeruk nipis","1 sendok makan gula","2 irisan semangka kecil untuk hiasan"],
["Masukkan semua bahan kecuali irisan untuk hiasan ke dalam blender dan blender selama 30 detik.","Tuangkan ke dalam 2 gelas kecil, hiasi dengan irisan semangka, lalu nikmati!"],
["Tingkat kemanisan semangka berbeda-beda. Sesuaikan dengan menambahkan pemanis jika perlu.","Untuk diet pembatasan cairan, nikmati satu Minuman Penyegar Semangka Musim Panas sekarang dan bekukan satu porsi untuk nanti. Keluarkan dari freezer 10 hingga 15 menit sebelum disajikan.","Jika Anda menggunakan pengganti gula sebagai ganti gula, karbohidrat berkurang sebanyak 6 gram dan kalori menjadi 26 per porsi 6 ons."],
["1 buah, rendah kalium"]),
(1002629,"Ayam Panggang","Hidangan ayam ramah ginjal ini mendapatkan cita rasanya dari bawang putih dan rempah, dan minyak zaitun membantu menjaga ayam tetap lembap.","4","110 g",
["semprotan masak","450 gram dada ayam tanpa tulang","2 sendok makan bawang putih","1/2 sendok teh lada hitam","1 sendok makan minyak zaitun","1/4 cangkir air lemon","1-1/2 sendok teh paprika bubuk"],
["Panaskan oven terlebih dahulu hingga 177° C. Lapisi loyang dengan semprotan masak.","Letakkan dada ayam di atas loyang.","Cincang halus bawang putih.","Dalam wadah kecil, campurkan lada, minyak zaitun, air lemon, dan bawang putih. Aduk rata.","Oleskan campuran lemon di atas dada ayam.","Taburkan paprika bubuk secara merata di atas dada ayam dan panggang selama 35 menit atau hingga ayam mencapai suhu internal 165° F atau 74° C.","Biarkan dada ayam beristirahat, ditutup dengan aluminium foil, selama 10-15 menit sebelum diiris atau disajikan."],
["Bumbu alami seperti oregano atau daun salam dapat ditambahkan untuk cita rasa yang lebih kaya."],
["3-1/2 daging"]),
(1002644,"Burrito Ayam","Burrito adalah hidangan yang dibungkus dalam tortilla. Burrito ayam ini dari ahli gizi DaVita di Kolombia memadukan sayuran dengan dada ayam dan krim keju dalam bungkus tortilla jagung.","4","2 burrito",
["4 lembar daun selada","40 g bawang bombai putih","40 g paprika hijau","40 g tomat hijau","15 mL minyak sayur","1/8 sendok teh garam","lada secukupnya","250 g dada ayam","8 tortilla jagung sedang untuk burrito","100 g krim keju oles"],
["Cuci selada dengan sangat bersih dan keringkan. Sobek dengan tangan menjadi potongan kecil.","Potong bawang bombai, paprika (yang sudah dicuci dan dibuang bijinya) dan tomat yang sudah dikupas menjadi irisan tipis (korek api).","Masukkan sedikit minyak sayur bersih dalam wajan dan tumis sayuran ini dengan sedikit garam dan lada.","Potong dada ayam menjadi potongan kecil.","Setelah sayuran matang, tambahkan potongan ayam.","Aduk dengan api kecil selama 3 atau 4 menit.","Letakkan selapis selada serta ayam dan sayuran tumis di atas tortilla jagung.","Tambahkan krim keju (sebagai saus).","Gulung tortilla."],
["Untuk mengurangi lemak, Anda dapat menggunakan krim keju rendah lemak.","Untuk mengurangi natrium, Anda dapat membumbui sayuran dan ayam dengan bumbu alami seperti bawang putih, oregano, dan daun salam sebagai pengganti garam."],
["2 daging","2 pati","1/2 sayuran, rendah kalium","1-1/2 lemak"]),
(1002647,"Fillet Ikan Kod Panggang Foil dengan Paprika","Resep ramah ginjal untuk fillet ikan kod yang dipanggang dalam foil dengan paprika ini pasti akan disukai saat Anda menyajikannya pada hidangan berikutnya.","4","2 ons",
["12 ons fillet ikan kod segar atau beku (yang sudah dicairkan)","1 lemon, diiris tipis","1/3 sendok teh garam","1/2 sendok teh lada hitam","4 ons paprika dalam toples yang dicincang, tanpa tambahan garam","1 sendok makan penuh minyak zaitun"],
["Panaskan oven terlebih dahulu hingga 350° F.","Letakkan dua lembar aluminium foil tebal di atas permukaan kerja Anda.","Sebarkan separuh irisan lemon tipis di atas setiap lembar foil.","Letakkan fillet ikan kod di atas irisan lemon, 2 fillet atau sekitar 6 ons di atas setiap lembar foil.","Taburi setiap fillet dengan garam dan lada dalam jumlah yang sudah diukur.","Taburi setiap fillet dengan paprika cincang, lalu siram dengan minyak zaitun.","Lipat tepi foil untuk menutup ikan di dalamnya. Letakkan di atas loyang dan panggang selama 20 menit. Keluarkan fillet dari foil untuk disajikan."],
["Paprika merah panggang segar juga dapat digunakan sebagai pengganti.","Saat menambahkan garam dalam jumlah yang sangat kecil, cobalah mencampurnya dengan lada atau rempah bubuk lainnya. Gunakan botol garam isi ulang agar Anda dapat menaburkannya secara merata pada makanan."],
["<ul>","<li>2-1/2 daging</li>","<li>1 sayuran, rendah kalium</li>","</ul>"]),
(1002650,"Salad Kebun","Salad Kebun adalah salad sederhana yang mudah dibuat dengan 5 jenis sayuran ramah ginjal.","2","1/2 resep",
["100 gram (1-1/2 cangkir) selada","30 gram (1/2 cangkir) kubis","1 batang seledri","1/2 paprika merah","1 wortel sedang","1 sendok teh (15 mL) air lemon"],
["Sobek selada menjadi potongan.","Potong kubis, seledri, dan paprika menjadi irisan korek api.","Parut wortel.","Campurkan semuanya dalam mangkuk dan tambahkan satu sendok teh air lemon atau cuka.","Sajikan segera."],
["Anda dapat mengganti kubis dengan mentimun atau labu.","Anda dapat mengganti air lemon dengan cuka putih."],
["1-1/2 sayuran, kalium sedang"]),
]
